'use strict';
const base=document.body.dataset.base||'./';
const names={'sam-tuoi':'Sâm Nữ Hoàng tươi','sam-kho':'Sâm Nữ Hoàng khô','ruou-sam':'Ngự Vị Nữ Hoàng Tửu','cao-sam':'Cao Sâm Nữ Hoàng','trong-go-soi':'Ngự Vị Nữ Hoàng Tửu — Trống rượu gỗ sồi','binh-dang-trong':'Ngự Vị Nữ Hoàng Tửu — Bình thủy tinh dáng trống','binh-da-giac':'Ngự Vị Nữ Hoàng Tửu — Bình thủy tinh đa giác','binh-ho-lo':'Ngự Vị Nữ Hoàng Tửu — Bình hồ lô','chai-thuy-tinh':'Ngự Vị Nữ Hoàng Tửu — Chai thủy tinh'};
const wineKeys=['trong-go-soi','binh-dang-trong','binh-da-giac','binh-ho-lo','chai-thuy-tinh'];
const pathFor=key=>'san-pham/'+(wineKeys.includes(key)?'ruou-sam/':'')+key+'/';
let saved=[],note='',storageOK=true;
try{const raw=JSON.parse(localStorage.getItem('snh-interest')||'[]');saved=Array.isArray(raw)?[...new Set(raw.filter(x=>Object.hasOwn(names,x)))]:[];note=localStorage.getItem('snh-note')||'';}catch{storageOK=false;}
function notify(text){const el=document.querySelector('.toast');el.textContent=text;el.classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.classList.remove('visible'),3800);}
function persist(){try{localStorage.setItem('snh-interest',JSON.stringify(saved));return true;}catch{storageOK=false;notify('Trình duyệt không cho phép lưu. Danh sách chỉ giữ trong phiên hiện tại.');return false;}}
function render(){document.querySelectorAll('.saved-count').forEach(x=>x.textContent=saved.length);const count=document.getElementById('list-count');if(count)count.textContent=saved.length;const list=document.getElementById('inquiry-list');if(list){list.replaceChildren();if(!saved.length){const p=document.createElement('p');p.className='empty-list';p.append('Chưa có mẫu được lưu. ');const a=document.createElement('a');a.href=base+'san-pham/ruou-sam/';a.textContent='Khám phá bộ sưu tập ↗';p.append(a);list.append(p);}for(const key of saved){const row=document.createElement('div');row.className='inquiry-row';const a=document.createElement('a');a.href=base+pathFor(key);a.textContent=names[key];const b=document.createElement('button');b.textContent='Xóa';b.setAttribute('aria-label','Xóa '+names[key]);b.addEventListener('click',()=>{saved=saved.filter(x=>x!==key);persist();render();});row.append(a,b);list.append(row);}}document.querySelectorAll('[data-add]').forEach(b=>b.textContent=saved.includes(b.dataset.add)?'Đã lưu · Xem danh sách ↗':'Lưu mẫu quan tâm ＋');}
document.querySelectorAll('[data-add]').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.add;if(saved.includes(key)){location.href=base+'lien-he/';return;}if(!Object.hasOwn(names,key))return;saved.push(key);const ok=persist();render();if(ok)notify('Đã lưu đúng mẫu bạn quan tâm. Xem danh sách tại trang Liên hệ.');}));
const menu=document.querySelector('.menu-toggle'),nav=document.getElementById('main-nav');
function closeMenu(){menu?.setAttribute('aria-expanded','false');menu?.setAttribute('aria-label','Mở trình đơn');nav?.classList.remove('open');}
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Đóng trình đơn':'Mở trình đơn');nav.classList.toggle('open',open);});
window.addEventListener('resize',()=>{if(window.innerWidth>760)closeMenu();});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu?.getAttribute('aria-expanded')==='true'){closeMenu();menu.focus();}});
const header=document.querySelector('header');let scrollQueued=false;window.addEventListener('scroll',()=>{if(scrollQueued)return;scrollQueued=true;requestAnimationFrame(()=>{header?.classList.toggle('scrolled',window.scrollY>20);scrollQueued=false;});},{passive:true});
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').toLowerCase().trim();let wineFilter='all';
function filterWines(){const search=normalize(document.getElementById('wine-search')?.value||'');let count=0;document.querySelectorAll('[data-wine]').forEach(c=>{const material=wineFilter==='all'||(wineFilter==='wood'?c.dataset.wine==='trong-go-soi':c.dataset.wine!=='trong-go-soi');const show=material&&normalize(c.dataset.search).includes(search);c.hidden=!show;if(show){count++;c.classList.add('in-view');}});const status=document.getElementById('filter-status');if(status)status.textContent=count+' kiểu dáng phù hợp';const empty=document.getElementById('no-results');if(empty)empty.hidden=count>0;}
document.querySelectorAll('[data-wine-filter]').forEach(b=>b.addEventListener('click',()=>{wineFilter=b.dataset.wineFilter;document.querySelectorAll('[data-wine-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});filterWines();}));document.getElementById('wine-search')?.addEventListener('input',filterWines);
const main=document.querySelector('.main-photo');document.querySelectorAll('[data-thumbnail]').forEach(b=>b.addEventListener('click',()=>{if(!main)return;const img=main.querySelector('img');img.src=b.dataset.thumbnail;img.alt=b.dataset.caption;main.dataset.image=b.dataset.thumbnail;main.dataset.caption=b.dataset.caption;document.querySelectorAll('[data-thumbnail]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});}));
const dialog=document.getElementById('lightbox');let slides=[],slideIndex=0;
function paintSlide(){const slide=slides[slideIndex];if(!slide)return;const img=dialog.querySelector('img');img.src=slide.src;img.alt=slide.caption;dialog.querySelector('.lightbox-caption').textContent=slide.caption+' · '+(slideIndex+1)+' / '+slides.length;dialog.querySelectorAll('.lightbox-prev,.lightbox-next').forEach(b=>b.hidden=slides.length<2);}
function moveSlide(step){slideIndex=(slideIndex+step+slides.length)%slides.length;paintSlide();}
document.querySelectorAll('[data-image]').forEach(b=>b.addEventListener('click',()=>{const gallery=b.closest('.product-gallery');if(gallery){slides=Array.from(gallery.querySelectorAll('[data-thumbnail]')).map(x=>({src:x.dataset.thumbnail,caption:x.dataset.caption}));}else{slides=Array.from((b.closest('.gallery-group')||document).querySelectorAll('[data-image]')).map(x=>({src:x.dataset.image,caption:x.dataset.caption||'Ảnh sản phẩm'}));}slideIndex=Math.max(0,slides.findIndex(x=>x.src===b.dataset.image));paintSlide();dialog.showModal();}));
dialog?.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());dialog?.querySelector('.lightbox-prev').addEventListener('click',()=>moveSlide(-1));dialog?.querySelector('.lightbox-next').addEventListener('click',()=>moveSlide(1));dialog?.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();moveSlide(-1);}if(e.key==='ArrowRight'){e.preventDefault();moveSlide(1);}});dialog?.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
const textarea=document.getElementById('inquiry-note');if(textarea){textarea.value=note;textarea.addEventListener('input',()=>{note=textarea.value;try{localStorage.setItem('snh-note',note);}catch{if(storageOK){storageOK=false;notify('Ghi chú chỉ được giữ trong phiên hiện tại.');}}});}
document.getElementById('download-inquiry')?.addEventListener('click',()=>{if(!saved.length&&!note.trim()){notify('Chọn mẫu sản phẩm hoặc nhập nội dung bạn cần tư vấn.');return;}const text='SÂM NỮ HOÀNG — DANH SÁCH QUAN TÂM\nHộ kinh doanh cá thể Đỗ Thị Tuyết\nHotline: 0972 686 765\n\n'+saved.map((key,i)=>(i+1)+'. '+names[key]).join('\n')+'\n\nQUY CÁCH / SỐ LƯỢNG / NỘI DUNG CẦN TƯ VẤN\n'+note+'\n\nĐây là danh sách cá nhân, chưa phải đơn hàng và chưa được gửi tới hộ kinh doanh.\n';const u=URL.createObjectURL(new Blob(['\uFEFF',text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='sam-nu-hoang-mau-quan-tam.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);notify('Đã tạo tệp danh sách quan tâm.');});
render();
const reduce=window.matchMedia('(prefers-reduced-motion: reduce)');if('IntersectionObserver'in window&&!reduce.matches){try{const observer=new IntersectionObserver(entries=>{for(const item of entries){if(item.isIntersecting){item.target.classList.add('in-view');observer.unobserve(item.target);}}},{threshold:.08,rootMargin:'0px 0px 25px 0px'});document.querySelectorAll('.wine-grid,.photo-grid,.category-grid').forEach(grid=>Array.from(grid.children).forEach((x,i)=>x.style.setProperty('--delay',(i%3)*65+'ms')));document.querySelectorAll('.reveal').forEach(x=>observer.observe(x));document.documentElement.classList.add('motion-ready');}catch{document.documentElement.classList.remove('motion-ready');}}
